mapper.select:
/* isry.sample.mapper.TstBoardDevMapper.selectBoardList 공통팀 유민상 */
SELECT BRD_SEQ , TIT , CONT , ATTC_FILE_NO , TO_CHAR(WRI_DT, 'YYYY-MM-DD') as WRI_DT , WRI_NM FROM CMN_TMP_BOARD CTB WHERE 1=1
ORDER BY BRD_SEQ DESC OFFSET #{START_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY

mapper.insert:
	     /* isry.sample.mapper.TstBoardDevMapper.insertBoardList 공통팀 유민상 */


			  SELECT NVL(MAX(BRD_SEQ), 0) +1 AS BRD_SEQ
			  FROM CMN_TMP_BOARD


		INSERT INTO CMN_TMP_BOARD(
		      BRD_SEQ

			, TIT


			, CONT


            , ATTC_FILE_NO


			, WRI_DT


			, WRI_NM

		)VALUES(
		      #{BRD_SEQ}

			, #{TIT}


			, #{CONT}


            , #{ATTC_FILE_NO}


            , #{WRI_DT}


			, #{WRI_NM}

		)

mapper.update:
/* isry.sample.mapper.TstBoardDevMapper.updateBoardList 공통팀 유민상 */
 UPDATE CMN_TMP_BOARD SET


     TIT = #{TIT}


     , CONT = #{CONT}


     , ATTC_FILE_NO = #{ATTC_FILE_NO}


     , WRI_DT = #{WRI_DT}


     , WRI_NM = #{WRI_NM}

 WHERE BRD_SEQ = #{BRD_SEQ__origin}

mapper.delete:
/* isry.sample.mapper.TstBoardDevMapper.deleteBoardList 공통팀 유민상 */
 DELETE
 FROM CMN_TMP_BOARD
 WHERE BRD_SEQ = #{BRD_SEQ__origin}
